async function preview() { await busy('Validating the sample order and Oracle mappings…', async () => { notify(''); if (state.dirty) { state.draft = await api(`/api/drafts/${encodeURIComponent(state.draft.id)}`, { method: 'PUT', body: { version: state.draft.version, orders: state.draft.orders } }); state.dirty = false; } state.draft = await api(`/api/drafts/${encodeURIComponent(state.draft.id)}/preview`, { method: 'POST', body: { version: state.draft.version } }); renderDraft(); $('#preview-section').scrollIntoView({ behavior: 'smooth', block: 'start' }); }); }
async function accept() {
