   ('CANCEL','CHAR(1)','Cancelled flag',False,'N',None),
  ]},
 'ORDSTYLE': {
  'label':'Order style lines', 'description':'Garment, colour, and quantity lines under an order.',
  'fields':[
   ('ORDSTYLEID','NUMBER','Generated style-line ID',True,'Generated when saved',None),
   ('ORDMASID','NUMBER','Parent order ID',True,'From ORDMAS',None),
   ('STNO','NUMBER','Line number',True,'1',None),
   ('PONUM','VARCHAR2(55)','Buyer PO / contract',False,'VG8439288','po_number'),
