        if sum(len(l.get('sizes',[])) for o in data.orders for l in o.get('lines',[]))>5000:raise ValueError('Import exceeds 5,000 size rows.')
        d['orders']=store.edited_orders(d['orders'],data.orders);d['version']+=1;d['plan']=None
