 97	def find_cell(sheets, sheet_name, address):
 98	    sheet=next((s for s in sheets if s['name']==sheet_name),None)
 99	    if not sheet:raise ValueError('The selected worksheet no longer exists.')
100	    cell=next((c for c in sheet['cells'] if c['cell']==address),None)
101	    if not cell:raise ValueError(f'{sheet_name}!{address} is empty or unavailable.')
102	    return cell
