104	def table_mapping(draft, table, requested=None, sheet_name=None):
105	    if table not in TARGET_TABLES:raise ValueError('Select an available target table.')
106	    allowed={f[0] for f in TARGET_TABLES[table]['fields']}
107	    result={}
108	    if requested is None:
109	        order=(draft.get('orders') or [{}])[0]
110	        provenance=order.get('provenance',{})
111	        semantic={f[0]:f[5] for f in TARGET_TABLES[table]['fields'] if f[5]}
112	        for target,key in semantic.items():
113	            src=provenance.get(key)
114	            if isinstance(src,dict) and src.get('cell') and (not sheet_name or src.get('sheet')==sheet_name):
115	                result[target]={'sheet':src['sheet'],'cell':src['cell'],'mode':'automatic'}
116	        # Quantity is derived from the reviewed line sizes when it does not have one source cell.
117	        if table=='ORDMAS' and 'OQTY' not in result and order:
118	            qty=sum((s.get('quantity') or 0) for line in order.get('lines',[]) for s in line.get('sizes',[]) if isinstance(s.get('quantity'),(int,float)))
119	            if qty:result['OQTY']={'derived':True,'value':qty,'label':'Sum of reviewed size quantities','mode':'automatic'}
120	    else:
121	        for item in requested:
122	            target=str(item.get('target','')).upper()
123	            if target not in allowed:raise ValueError(f'{target or "Target field"} is not available for {table}.')
124	            cell=find_cell(draft['sheets'],str(item.get('sheet','')),str(item.get('cell','')).upper())
125	            mode='automatic' if item.get('mode')=='automatic' else 'manual'
126	            result[target]={'sheet':str(item['sheet']),'cell':cell['cell'],'mode':mode}
127	    preview={}
128	    for target,src in result.items():
129	        preview[target]=src.get('value') if src.get('derived') else find_cell(draft['sheets'],src['sheet'],src['cell'])['value']
130	    return {'table':table,'mappings':result,'preview':preview}
