118	function renderResult(result) { const rows = result.rows || []; const target = $('#result-section'); target.hidden = false; target.innerHTML = `<span class="success-icon">✓</span><h2>${result.already_committed ? 'This import was already saved.' : 'Your sample order is in Oracle.'}</h2><p>Import ${esc(result.job_id)} · ${esc(result.committed_at || '')}</p><div class="result-ids">${(result.orders || []).map(order => `<div class="result-id"><strong>${esc(order.order_ref)}</strong><small>ORDMASID ${esc(order.ordmasid)}</small></div>`).join('')}</div><details class="table-preview"><summary><strong>Verified saved records</strong><span class="subtle">${rows.length} records</span></summary>${rows.map(row => `<div class="table-wrap"><table><thead><tr><th colspan="2">${esc(row.table)}</th></tr></thead><tbody>${Object.entries(row.values || row.row || {}).map(([key, value]) => `<tr><td class="mono">${esc(key)}</td><td>${esc(display(value))}</td></tr>`).join('')}</tbody></table></div>`).join('')}</details><button class="button secondary" data-another-import>＋ Start another import</button>`; target.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
119	async function ensureTargetTables() { if (state.targetTables.length) return; const response = await api('/api/target-tables'); state.targetTables = response.tables || []; state.targetSource = response.source || ''; }
120	async function autoTableMapping(table = state.mapper.table, sheet = state.mapper.sheet) {
121	  state.mapper.table = table;
122	  state.draft = await api(`/api/drafts/${encodeURIComponent(state.draft.id)}/table-map`, { method: 'POST', body: { version: state.draft.version, table, sheet } });
123	}
124	function currentSheet() {
125	  const sheets = state.draft?.sheets || [];
126	  if (!state.mapper.sheet || !sheets.some(s => s.name === state.mapper.sheet)) state.mapper.sheet = sheets.find(s => !s.hidden)?.name || sheets[0]?.name || '';
127	  return sheets.find(s => s.name === state.mapper.sheet);
128	}
129	function sourceLabel(mapping) {
130	  if (!mapping) return '';
131	  if (mapping.derived) return mapping.label || 'Calculated value';
132	  return `${mapping.source_key ? `${mapping.source_key} → ` : ''}${mapping.sheet}!${mapping.cell}`;
133	}
134	function sourceValue(mapping) {
135	  if (!mapping) return null;
136	  if (mapping.derived) return mapping.value;
137	  try { return (state.draft.sheets.find(s => s.name === mapping.sheet)?.cells || []).find(c => c.cell === mapping.cell)?.value; } catch (_) { return null; }
138	}
139	function renderSourceGrid(sheet) {
140	  if (!sheet) return '<div class="empty-state">No worksheet is available.</div>';
141	  if (state.mapper.view === 'json') {
142	    const json = { name: sheet.name, rows: sheet.rows, columns: sheet.cols, merged: sheet.merged || [], cells: sheet.cells || [] };
143	    return `<pre class="json-preview" tabindex="0">${esc(JSON.stringify(json, null, 2))}</pre>`;
144	  }
145	  const rows = Math.min(sheet.rows || 0, 120); const cols = Math.min(sheet.cols || 0, 30);
146	  const byPosition = new Map((sheet.cells || []).map(cell => [`${cell.row}:${cell.col}`, cell]));
147	  const selected = state.mapper.selected;
148	  let body = '';
149	  for (let row = 1; row <= rows; row++) {
150	    body += `<tr><th class="row-number" scope="row">${row}</th>`;
151	    for (let col = 1; col <= cols; col++) {
152	      const cell = byPosition.get(`${row}:${col}`); const active = selected?.sheet === sheet.name && selected?.cell === cell?.cell;
153	      body += `<td class="sheet-cell ${active ? 'selected' : ''} ${cell?.hidden ? 'hidden-cell' : ''}">${cell ? `<button draggable="true" data-source-cell="${esc(cell.cell)}" title="${esc(sheet.name)}!${esc(cell.cell)}${cell.formula ? ` · Formula: ${cell.formula}` : ''}" aria-pressed="${active}">${esc(display(cell.value))}</button>` : ''}</td>`;
154	    }
155	    body += '</tr>';
156	  }
157	  const clipped = (sheet.rows > rows || sheet.cols > cols) ? `<p class="grid-note">Showing the first ${rows} rows and ${cols} columns. The complete worksheet is preserved in JSON.</p>` : '';
158	  return `<div class="sheet-scroll"><table class="sheet-grid"><thead><tr><th class="corner"></th>${Array.from({ length: cols }, (_, i) => `<th scope="col">${columnName(i + 1)}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>${clipped}`;
159	}
160	function renderDataMapper() {
161	  const host = $('#data-mapper'); if (!host || !state.draft) return;
162	  const sheet = currentSheet(); const selectedTable = state.targetTables.find(t => t.name === state.mapper.table) || state.targetTables[0];
163	  if (!selectedTable) { host.innerHTML = '<div class="empty-state">Loading target tables…</div>'; return; }
164	  state.mapper.table = selectedTable.name;
165	  const saved = state.draft.table_mappings?.[selectedTable.name] || (state.draft.table_mapping?.table === selectedTable.name ? state.draft.table_mapping : { mappings: {}, preview: {} });
166	  const mappedCount = Object.keys(saved.mappings || {}).length;
167	  const requiredMissing = selectedTable.fields.filter(f => f.required && !saved.mappings?.[f.name] && !/Generated|From ORDMAS/.test(f.sample)).length;
