frontend/app.js:170:    <section class="mapper-stage source-stage"><div class="stage-heading"><span class="stage-number">1</span><div><h3>Uploaded Excel</h3><p>Check the original workbook at full width. Select any cell you want to map manually.</p></div><div class="stage-controls"><label>Worksheet<select id="source-sheet">${(state.draft.sheets || []).map(s => `<option value="${esc(s.name)}" ${s.name === sheet?.name ? 'selected' : ''}>${esc(s.name)}${s.hidden ? ' · hidden' : ''}</option>`).join('')}</select></label><div class="view-toggle" role="group" aria-label="Source view"><button data-source-view="grid" class="${state.mapper.view === 'grid' ? 'active' : ''}" aria-pressed="${state.mapper.view === 'grid'}">Excel grid</button><button data-source-view="json" class="${state.mapper.view === 'json' ? 'active' : ''}" aria-pressed="${state.mapper.view === 'json'}">JSON</button></div></div></div><div class="source-pane source-wide"><div class="pane-title"><div><strong>${esc(sheet?.name || '')}</strong><span>${formatNumber(sheet?.cells?.length || 0)} populated cells</span></div><span class="selection-readout">${esc(selectedText)}</span></div>${renderSourceGrid(sheet)}</div></section>
frontend/app.js:171:    <section class="mapper-stage table-stage"><div class="stage-heading"><span class="stage-number">2</span><div><h3>Select the Oracle table</h3><p>The dropdown and its columns come from ${state.targetSource === 'oracle-live' ? 'the connected Oracle owner' : 'the saved Oracle schema'}.</p></div></div><div class="table-choice"><label>Oracle target table<select id="target-table">${state.targetTables.map(t => `<option value="${esc(t.name)}" ${t.name === selectedTable.name ? 'selected' : ''}>${esc(t.name)}${t.label && t.label.toUpperCase() !== t.name.toUpperCase() ? ` · ${esc(t.label)}` : ''}</option>`).join('')}</select></label><button id="auto-map-table" class="button primary">Match JSON keys</button><div class="selected-source"><span>Selected source cell</span><strong>${esc(selectedText)}</strong></div><span class="schema-badge">${state.targetSource === 'oracle-live' ? 'Live Oracle schema' : 'Saved Oracle schema'}</span></div></section>
frontend/app.js:172:    <section class="mapper-stage target-stage"><div class="stage-heading"><span class="stage-number">3</span><div><h3>Review what will be applied</h3><p>Matched values appear first. For anything missing, select a cell above and choose Map here.</p></div><div class="mapper-stats"><span><strong>${mappedCount}</strong> mapped</span><span class="${requiredMissing ? 'needs-attention' : ''}"><strong>${requiredMissing}</strong> required missing</span></div></div><div class="target-pane target-wide"><div class="pane-title target-title"><div><strong>${esc(selectedTable.name)}</strong><span>${esc(selectedTable.description)}</span></div><label class="field-search"><span class="visually-hidden">Filter target fields</span><input id="field-filter" type="search" placeholder="Filter ${selectedTable.fields.length} fields" autocomplete="off"></label></div><div class="target-scroll"><table class="target-grid"><thead><tr><th>ORACLE FIELD</th><th>TYPE</th><th>EXCEL SOURCE</th><th>VALUE TO APPLY</th><th>ACTION</th></tr></thead><tbody>${[...selectedTable.fields].sort((a,b) => Number(!!saved.mappings?.[b.name])-Number(!!saved.mappings?.[a.name]) || Number(b.required)-Number(a.required) || a.ordinal-b.ordinal).map(field => { const mapping = saved.mappings?.[field.name]; const value = saved.preview?.[field.name] ?? sourceValue(mapping); return `<tr data-target-field="${esc(field.name)}" data-field-search="${esc(`${field.name} ${field.label} ${field.type}`.toLowerCase())}" class="${mapping ? 'mapped' : ''} ${field.required && !mapping ? 'required-missing' : ''}"><td><strong>${esc(field.name)}</strong><span>${esc(field.label)}${field.required ? ' · required' : ''}</span></td><td class="mono">${esc(field.type)}</td><td>${mapping ? `<span class="map-source">${esc(sourceLabel(mapping))}</span><small>${mapping.mode === 'manual' ? 'Mapped by you' : 'Matched by JSON key'}</small>` : `<span class="unmapped">No source selected</span><small>${esc(field.sample)}</small>`}</td><td class="preview-value">${mapping ? esc(display(value)) : '—'}</td><td><button class="map-here" data-map-target="${esc(field.name)}" ${state.mapper.selected ? '' : 'disabled'}>${mapping ? 'Replace' : 'Map here'}</button></td></tr>`; }).join('')}</tbody></table></div></div><div class="mapping-note">This section previews the source-to-target mapping. Oracle is unchanged until the final database preview is accepted.</div></section>`;

